from common import *
SEMIO=''
semio=[
('normal','La fonction normale : transporter et perfuser',"L’hémoglobine des hématies transporte l’oxygène ; la circulation l’amène aux tissus. Le nombre de transporteurs, leur saturation et le débit sont des dimensions différentes. La moelle renouvelle les éléments figurés, tandis que l’hémostase limite les pertes après une lésion. Cette organisation explique pourquoi un seul examen ne peut résumer une hémorragie.",['NORMAL','NORMAL-RBC','NORMAL-HEMO']),
('signs','Des signes à observer ensemble',"La pâleur et l’asthénie peuvent accompagner l’anémie. La dyspnée, les vertiges, la syncope ou la douleur thoracique renseignent la tolérance. L’hypotension, les marbrures, l’oligurie et les troubles de conscience font rechercher une mauvaise perfusion. Leur importance dépend de la vitesse d’installation et du terrain ; aucun ne démontre à lui seul le mécanisme.",['HUG']),
('mechanisms','Deux perturbations qui se renforcent',"La perte de sang peut réduire le volume circulant et la masse érythrocytaire. Une réponse cardiovasculaire compense une partie du déficit, mais elle n’est pas toujours suffisante. Les mouvements de liquide et les perfusions modifient ensuite la concentration d’hémoglobine. Une saturation normale ne corrige pas la diminution du nombre de molécules d’hémoglobine disponibles.",['TRAUMA','NORMAL-RBC','HUG']),
('examination','Choisir une mesure pour une question',"L’examen répété recherche la source et la tolérance. La numération mesure une concentration et des populations cellulaires ; le lactate renseigne la perturbation de perfusion ; les tests d’hémostase étudient la capacité à former un caillot. L’échographie et le scanner explorent des lésions et compartiments. Le choix de leur ordre dépend de la nécessité d’une hémostase immédiate.",['TRAUMA','HUG']),
('interpretation','L’heure du résultat fait partie du résultat',"Relier le prélèvement au début du saignement, au remplissage et aux produits transfusés. Une première hémoglobine normale peut être trompeuse ; une diminution ultérieure peut associer perte et dilution. Le lactate peut aussi varier avec sa clairance. Les références du laboratoire et le contexte évitent d’appeler chaque variation une aggravation du même mécanisme.",['TRAUMA']),
('differentials','Distinguer sans exclure les associations',"Une réticulocytose se rencontre dans la réponse à une perte mais aussi dans l’hémolyse. Ictère, marqueurs de destruction et immunohématologie orientent la seconde hypothèse. La carence chronique et l’inflammation modifient les indices et les réserves en fer. Un antécédent d’anémie ou une maladie médullaire peut expliquer une partie du résultat actuel.",['HUG','HUG-OLD','MEDIX']),
('urgency','Reconnaître le moment où il faut agir',"Un choc avec source évidente ou probable impose le circuit de contrôle urgent du saignement. Une altération de conscience, une mauvaise perfusion ou une douleur thoracique ne doivent pas attendre le franchissement d’un seuil d’hémoglobine. Les objectifs de pression et les schémas hémostatiques diffèrent entre traumatisme, saignement digestif et contexte obstétrical.",['TRAUMA','HUG','WHO-PPH','ESGE']),
('limits','Ce que la sémiologie ne permet pas d’affirmer',"Le volume perdu n’est pas calculable avec exactitude à partir d’un signe isolé, d’une photographie de frottis ou d’un seul chiffre d’hémoglobine. Les fréquences et sensibilités spécifiques àD62 ne sont pas établies dans ce dossier. Les objectifs de patients stables ne sont pas des seuils universels en hémorragie active ; une amélioration transitoire ne certifie pas l’arrêt définitif de la perte.",['TRAUMA','HUG','BLOOD-IMAGE']),
('sources','Sources, populations et décisions',"Le cadre suisse de premier recours est confronté à la directive européenne de traumatologie2023, àESGE2026 et aux textes obstétricauxSGGG2022 etOMS2025. Les textes n’ont pas tous le même niveau de preuve ni la même population. Les fiches suisses de produits sont datées et leurs divergences sont enseignées ; les décisions restent liées au contexte réellement étudié.",['HUG','TRAUMA','ESGE','PPH-CH','WHO-PPH','TXA'])]
for marker,title,body,sources in semio:
 heading=f'<h3>{title}</h3>' if marker!='normal' else f'<h3>Pour la leçon : quelle est la sémiologie fondamentale et analytique ?</h3><h4>{title}</h4>'
 SEMIO+=f'<section class="ilot" id="d62-semio-{marker}" data-semiology="{marker}">{heading}<p>{body}</p>{refs(*sources)}</section>'
SEMIO+=causal('d62-causal-semio','Du mécanisme à la décision',['Perte récente : quantité et volume','Signes de tolérance + mesures datées','Source à contrôler, support à adapter','Réévaluation clinique et biologique'],'Cette chaîne résume les recommandationsHUG et européennes ; elle ne remplace pas un protocole de réanimation.')+refs('HUG','TRAUMA')

ANAT='''<h3>Les compartiments : circulation, moelle et lieu de perte</h3>
<p>Le sang circule dans le système vasculaire. Une lésion peut permettre sa sortie vers l’extérieur ou vers un espace interne. Le lieu où le sang est perdu détermine ce qui est visible et quels examens sont utiles. La quantité aperçue dans une plaie, des selles ou un drain n’est pas automatiquement la totalité de la perte.</p>
<p>En traumatologie thoracoabdominale, les examens ciblés cherchent notamment du liquide dans les espaces accessibles à l’échographie ; le scanner injecté peut préciser lésions et source. Ces moyens ne sont pas interchangeables. La stabilité du patient et l’existence d’une source exigeant un contrôle immédiat déterminent la place de l’imagerie.</p>
<p>La moelle hématopoïétique est un autre compartiment. Elle produit les nouvelles cellules sanguines et les libère dans la circulation. La photographie situe ce tissu à l’intérieur de l’os ; elle ne représente ni un réservoir de sang immédiatement mobilisable ni une image de l’hémorragie du patient.</p>
'''+original('marrow','d62-science-marrow')+'''
<p>Cette distinction guide les examens : un prélèvement sanguin observe ce qui circule, une imagerie cherche une lésion ou une collection, et un examen médullaire explore une production anormale lorsqu’une telle hypothèse est pertinente. Une hémorragie expliquée n’impose pas à elle seule une exploration médullaire systématique.</p>
<p>Le contrôle de la source doit viser le compartiment responsable. Remplacer des globules rouges améliore le transport d’oxygène mais ne ferme pas une lésion. Inversement, l’hémostase obtenue n’annule pas immédiatement l’anémie résiduelle. Les deux actions répondent à deux problèmes anatomiques et fonctionnels distincts.</p>
'''+refs('NORMAL','NORMAL-IMAGE','TRAUMA','HUG')

HISTO='''<h3>Les cellules : forme, nombre et maturation</h3>
<p>Les hématies matures contiennent l’hémoglobine qui transporte l’oxygène. Le frottis permet de regarder leur morphologie et leur distribution sur une lame ; la numération apporte les quantités et indices mesurés. Un champ photographié, même très riche en cellules, ne révèle pas à lui seul la concentration d’hémoglobine du patient.</p>
'''+original('blood','d62-science-blood')+'''
<p>Le volume globulaire moyen décrit la taille moyenne des hématies ; la teneur corpusculaire et la concentration corpusculaire décrivent d’autres relations avec l’hémoglobine. Une moyenne peut masquer plusieurs populations ou mécanismes associés. Les valeurs de référence doivent être celles de la méthode et de la population examinées.</p>
<p>La stratégieHUG2022 propose, à titre de repère daté, un volume globulaire moyen de82–98fL. En dessous, elle parle de microcytose ; au-dessus, de macrocytose. Un tableau de gradation et les limites figurent dans la fenêtre sur les indices. Cette plage ne devient pas une norme nationale universelle.</p>
<p>Les réticulocytes sont des cellules érythrocytaires encore immatures. Leur nombre renseigne la réponse de production et doit être rapproché de la sévérité de l’anémie et de la chronologie. Le documentHUG associe une réponse régénérative à l’hémorragie ou à l’hémolyse ; cette association ne constitue pas une preuve de l’une des deux causes. Le faible grossissement de l’image ci-dessus ne permet pas de les identifier de manière fiable.</p>
<p>Une carence en fer préexistante, une inflammation, une maladie de production ou une transfusion peuvent compliquer l’interprétation du tableau cellulaire. Un saignement aigu ne se diagnostique donc pas par une « image typiqueD62 ». Il se comprend par la concordance entre histoire, évolution biologique et source documentée.</p>
'''+refs('NORMAL-RBC','HUG','BLOOD-IMAGE','MEDIX')

PHYSIO='''<h3>Transport d’oxygène : quantité, saturation et circulation</h3>
<p>Une molécule d’hémoglobine peut fixer de l’oxygène. La saturation décrit la part des sites occupés, alors que la concentration d’hémoglobine décrit la quantité de transporteurs par volume. Ces deux variables répondent à des questions différentes. Une saturation conservée ne signifie pas qu’il existe assez de transporteurs pour tous les besoins tissulaires.</p>
<p>Le sang doit aussi atteindre les organes. Une perte de volume peut altérer la circulation, en plus de la perte de globules rouges. Le corps mobilise des réponses compensatrices, dont l’augmentation de la fréquence et de l’éjection cardiaques décrite parHUG. Leur efficacité dépend du terrain et du rythme de la perte ; une maladie cardiaque peut réduire la tolérance.</p>
'''+causal('d62-causal-oxygene','Pourquoi saturation et hémoglobine ne suffisent pas seules',['Hémoglobine : quantité de transporteurs','Saturation : proportion de sites occupés','Circulation : acheminement aux tissus','Tolérance clinique et perfusion à vérifier'],'Trois dimensions complémentaires ; aucune valeur numérique de débit ou de contenu artériel n’est calculée à partir de ce seul schéma.')+'''
<p>L’hypoperfusion peut augmenter la production de lactate et modifier l’équilibre acido-basique. La directive européenne recommande le lactate pour estimer et suivre la perturbation, avec le déficit de base comme alternative si la mesure n’est pas disponible. Cependant, une clairance hépatique altérée influence aussi le lactate et d’autres causes d’acidose modifient le déficit de base.</p>
<p>La production érythrocytaire dépend de la moelle, du signal érythropoïétique et des substrats, notamment le fer. Elle intervient dans la récupération ; son évaluation ne remplace pas le soutien immédiat d’une circulation défaillante. De même, la réponse réticulocytaire se lit avec le moment du prélèvement et les causes associées.</p>
<p>La concentration d’hémoglobine est sensible aux changements de volume plasmatique. Les séries de résultats deviennent plus instructives lorsqu’elles sont reliées aux pertes et aux traitements. Cette lecture dynamique explique pourquoi une décision de transfusion dans le choc ne peut dépendre d’un seul seuil emprunté à une population stable.</p>
'''+refs('NORMAL','NORMAL-RBC','HUG','TRAUMA')

BIO='''<h3>Hémostase et fer : arrêter la perte, puis reconstruire</h3>
<p>L’hémostase mobilise les plaquettes et la coagulation pour stabiliser une lésion vasculaire. La fibrine forme une composante du caillot ; sa dégradation fait intervenir le système fibrinolytique. Le traitement peut viser un déficit de facteurs, un manque de plaquettes ou une dégradation excessive, mais ces mécanismes ne sont pas équivalents.</p>
<p>En hémorragie majeure, la directive européenne recommande de surveiller régulièrement plaquettes, fibrinogène et paramètres de coagulation, éventuellement avec des méthodes viscoélastiques. La température et le calcium ionisé ont également une importance fonctionnelle. Remplacer uniquement des hématies ne corrige pas nécessairement les autres perturbations.</p>
'''+causal('d62-causal-txa','La cible de l’acide tranexamique',['Plasminogène et système fibrinolytique','TXA : limite l’activation en plasmine','Dégradation de la fibrine réduite','Bénéfice dépendant du contexte et du délai'],'Mécanisme décrit dans laFI suisse ; il ne prouve pas un bénéfice dans tout saignement et ne justifie pas l’usage digestif déconseillé parESGE.')+'''
<p>LeTXA se lie au plasminogène et limite sa conversion en plasmine ; laFI décrit ainsi une action antifibrinolytique. Il ne produit pas de nouvelles hématies et n’apporte pas de facteurs de coagulation. Cette distinction explique à la fois son association à d’autres mesures dans certaines hémorragies et l’impossibilité de l’utiliser comme substitut à une transfusion indiquée.</p>
<p>Après la perte, le fer redevient un substrat essentiel à la synthèse d’hémoglobine. Un traitement martial doit tenir compte des réserves, de l’inflammation et de l’absorption ou de la tolérance digestive. La ferritine est utile mais son élévation inflammatoire peut masquer une carence ; le contexte postpartum en est un exemple explicitement traité par l’OMS.</p>
<p>La voie intraveineuse contourne certaines limites de la voie orale, au prix de précautions propres au produit : hypersensibilité et, pour le carboxymaltose ferrique, risque d’hypophosphatémie. Le besoin total calculé, la dose autorisée par administration et la vitesse ne doivent pas être confondus. Une quantité de fer n’est pas un objectif d’hémoglobine immédiat.</p>
'''+refs('NORMAL-HEMO','TRAUMA','TXA','ESGE','MEDIX','FERINJECT','WHO-PPH')

IMMUNO='''<h3>Transfuser implique une compatibilité biologique et une identité certaine</h3>
<p>Les cellules transfusées portent des antigènes. Des anticorps du receveur dirigés contre des antigènes érythrocytaires peuvent entraîner une destruction accélérée des cellules transfusées. Swissmedic distingue les réactions hémolytiques aiguës et retardées, ainsi que les mécanismes intravasculaires et extravasculaires. Une anémie après transfusion n’est donc pas automatiquement une nouvelle perte sanguine.</p>
<p>La concordance de l’identité est une étape biologique de sécurité : un produit correctement préparé pour une autre personne peut être incompatible avec le receveur présent. La procédureHUG2025 demande de vérifier l’identité, le bracelet, les documents et le produit, puis les contrôles de compatibilité prévus. Un résultat ancien ou une étiquette supposée correcte ne remplace pas le contrôle au lit.</p>
<p>Si une réaction hémolytique est suspectée, l’investigation associe contrôle documentaire, groupe, recherche d’anticorps, test de compatibilité et test direct à l’antiglobuline selon le laboratoire. Une haptoglobine diminuée, une bilirubine et une lactate-déshydrogénase augmentées ou une réponse insuffisante de l’hémoglobine orientent vers une destruction ; aucun marqueur n’est interprété seul.</p>
<p>Une dyspnée après transfusion peut relever de plusieurs mécanismes. LeTACO correspond à une surcharge circulatoire. LeTRALI correspond à une atteinte pulmonaire associée à la transfusion, sans preuve de surcharge ventriculaire gauche dans la définitionSwissmedic2024 citée. Des mécanismes immunologiques ou d’activation des neutrophiles sont décrits ; les deux situations ne se traitent pas comme un simple déficit persistant d’hémoglobine.</p>
<p>La première réponse à une réaction suspecte consiste à arrêter la transfusion et à alerter selon le protocole local. La poche et le matériel sont conservés pour investigation. L’hémovigilance classe séparément la gravité et l’imputabilité : un événement très grave peut avoir une causalité encore incertaine, et cette incertitude ne justifie pas de le taire.</p>
'''+causal('d62-causal-immuno','Sécurité avant et après le produit',['Identité et produit concordants','Compatibilité selon le laboratoire','Surveillance de la réaction clinique','Arrêt et investigation si suspicion'],'La concordance évite une erreur de receveur ; la surveillance recherche les complications qui restent possibles malgré les contrôles.')+refs('HUG-TRANS','SWISSMED')

TABS=[('semio','Sémiologie fondamentale et analytique',SEMIO),('anat','Anatomie',ANAT),('histo','Histologie',HISTO),('physio','Physiologie',PHYSIO),('bio','Biochimie et hémostase',BIO),('immuno','Immunohématologie',IMMUNO)]
LINKS={
'semio':('Perte et tolérance produisent des signes complémentaires.','Relier clinique et mesures horodatées.','Agir sur source et perfusion sans attendre un chiffre isolé.'),
'anat':('Le site de perte détermine une partie des manifestations.','Imagerie et sang explorent des compartiments différents.','Contrôler la source et remplacer ce qui manque sont deux actions distinctes.'),
'histo':('Morphologie, moyenne et quantité ne sont pas identiques.','Frottis et numération se complètent.','Ne pas choisir une transfusion à partir d’une photographie.'),
'physio':('Quantité d’hémoglobine, saturation et circulation conditionnent l’apport.','La trajectoire clinique et biologique compte.','Adapter le support au mécanisme et à la tolérance.'),
'bio':('Caillot, fibrinolyse et disponibilité du fer répondent à des fonctions différentes.','Mesurer les déficits pertinents selon le contexte.','TXA, produits sanguins et fer ne sont pas interchangeables.'),
'immuno':('L’incompatibilité peut détruire les hématies transfusées.','Identité, compatibilité et investigation d’une réaction sont essentielles.','Arrêter et signaler une réaction suspecte, puis traiter son mécanisme.')}
def sciences():
 s='<div class="panel" id="pS" hidden><div class="sci-bar ui" role="tablist">'
 for k,t,_ in TABS:s+=f'<button id="d62-tab-{k}" role="tab" aria-selected="{str(k=="semio").lower()}" aria-controls="d62-s-{k}" data-s="d62-s-{k}">{t}</button>'
 s+='</div><div class="chap-body sci-body">'
 for k,t,b in TABS:
  bridge='<div class="key">'+''.join(f'<p><b>{a}</b> {v}</p>' for a,v in zip(['Science → clinique.','Science → examen.','Science → traitement.'],LINKS[k]))+'<p><b>À retenir.</b> Relier le mécanisme, la mesure et la décision avec leurs limites.</p></div>'
  body=b if k=='semio' else f'<section class="ilot" id="d62-s-{k}-cours">{b}</section>'
  hide='' if k=='semio' else ' hidden'
  s+=f'<div class="sci" id="d62-s-{k}" role="tabpanel" aria-labelledby="d62-tab-{k}"{hide}>{body}{bridge}<button class="pareto-btn ui" data-k="pareto-d62-{k}">▲ Loi de Pareto — {t}</button></div>'
 return s+'</div><div class="pager ui"><button class="prev">← Partie précédente</button><span></span><button class="next">Partie suivante →</button></div></div>'
